SELECT u.nid, u.eid, u.oid FROM (SELECT e.src AS nid, e.id AS eid, f.id AS oid, f.ord AS ord, e.seq AS seq FROM unnest(CAST($1 AS uuid[])) WITH ORDINALITY AS f(id, ord) JOIN anchors e ON e.kind = 'EdgeAnchor' AND e.arch_type = 'HasMember' AND e.dst = f.id AND (e.src_type = 'Forum' OR (e.src_type IS NULL AND EXISTS (SELECT 1 FROM anchors n WHERE n.id = e.src AND n.kind = 'NodeAnchor' AND n.arch_type = 'Forum'))) AND e.props->'archetype'->'joinDate' > to_jsonb(CAST($2 AS bigint)) UNION ALL SELECT e.dst AS nid, e.id AS eid, f.id AS oid, f.ord AS ord, e.seq AS seq FROM unnest(CAST($1 AS uuid[])) WITH ORDINALITY AS f(id, ord) JOIN anchors e ON e.kind = 'EdgeAnchor' AND e.arch_type = 'HasMember' AND e.src = f.id AND e.undirected AND e.dst <> f.id AND (e.dst_type = 'Forum' OR (e.dst_type IS NULL AND EXISTS (SELECT 1 FROM anchors n WHERE n.id = e.dst AND n.kind = 'NodeAnchor' AND n.arch_type = 'Forum'))) AND e.props->'archetype'->'joinDate' > to_jsonb(CAST($2 AS bigint))) u ORDER BY u.ord, u.seq, u.eid